const children = $('Build Dashboard Data').first().json.children || [];
const newsletters = $input.all().filter(function(i) { return i.json.newsletter_id !== undefined; }).map(function(i) { return i.json; });
const nlMap = {};
newsletters.forEach(function(n) { nlMap[n.child_id] = n; });
const merged = children.map(function(c) {
  const nl = nlMap[c.child_id];
  return {
    child_id: c.child_id,
    child_name: c.child_name,
    nickname: c.nickname,
    parent_name: c.parent_name,
    parent_email: c.parent_email,
    status: nl ? nl.status : 'Not Created',
    newsletter_id: nl ? nl.newsletter_id : null,
    ai_text: nl ? nl.ai_text : '',
    final_text: nl ? nl.final_text : '',
    staff_memo: nl ? nl.staff_memo : '',
    photo_count: nl ? nl.photo_count : 0,
  };
});
return [{ json: { merged: merged } }];

const body = $input.first().json.body;
const childId = body && body.child_id;
const photo1 = body && body.photo_1_b64;
if (!photo1 || photo1 === '') {
  return [{ json: { error: 'Please upload at least 1 photo', valid: false } }];
}
if (!childId) {
  return [{ json: { error: 'Child ID is required', valid: false } }];
}
const todayJST = new Date().toLocaleDateString('sv-SE', { timeZone: 'Asia/Tokyo' });
return [{
  json: {
    valid: true,
    child_id: childId,
    newsletter_id: childId + '_' + todayJST,
    date: todayJST,
    memo: body.memo || '',
    photo_1_b64: body.photo_1_b64 || '',
    photo_2_b64: body.photo_2_b64 || '',
    photo_3_b64: body.photo_3_b64 || '',
    photo_count: [body.photo_1_b64, body.photo_2_b64, body.photo_3_b64].filter(function(p) { return p && p !== ''; }).length,
  }
}];

const item = $input.first().json;
const userContent = [];
if (item.memo) { userContent.push({ type: 'text', text: 'Staff memo: ' + item.memo }); }
const toUrl = function(b64) {
  if (!b64) return null;
  if (b64.startsWith('data:')) return b64;
  return 'data:image/jpeg;base64,' + b64;
};
const photos = [item.photo_1_b64, item.photo_2_b64, item.photo_3_b64].filter(Boolean);
photos.forEach(function(p) {
  const url = toUrl(p);
  if (url) userContent.push({ type: 'image_url', image_url: { url: url } });
});
const systemPrompt = 'You are an expert at writing daycare newsletters for parents. Based on the photos and staff memo, output exactly one newsletter message within 100 characters.';
return [{ json: {
  child_id: item.child_id,
  newsletter_id: item.newsletter_id,
  date: item.date,
  memo: item.memo,
  photo_1_b64: item.photo_1_b64,
  photo_2_b64: item.photo_2_b64,
  photo_3_b64: item.photo_3_b64,
  photo_count: item.photo_count,
  systemPrompt: systemPrompt,
  userContent: JSON.stringify(userContent),
} }];

const prev = $('Build OpenAI Messages').first().json;
const resp = $input.first().json;
let aiText = '';
try {
  aiText = resp.choices[0].message.content.trim().slice(0, 100);
} catch(e) {
  return [{ json: { error: 'AI text generation failed', valid: false } }];
}
return [{ json: {
  valid: true,
  child_id: prev.child_id,
  newsletter_id: prev.newsletter_id,
  date: prev.date,
  memo: prev.memo,
  photo_1_b64: prev.photo_1_b64,
  photo_2_b64: prev.photo_2_b64,
  photo_3_b64: prev.photo_3_b64,
  photo_count: prev.photo_count,
  ai_text: aiText,
} }];

const nl = $input.first().json;
const userContent = [];
if (nl.staff_memo) { userContent.push({ type: 'text', text: 'Staff memo: ' + nl.staff_memo }); }
const toUrl = function(b64) {
  if (!b64) return null;
  if (b64.startsWith('data:')) return b64;
  return 'data:image/jpeg;base64,' + b64;
};
const photos = [nl.photo_1_binary, nl.photo_2_binary, nl.photo_3_binary].filter(Boolean);
photos.forEach(function(p) {
  const url = toUrl(p);
  if (url) userContent.push({ type: 'image_url', image_url: { url: url } });
});
const systemPrompt = 'You are an expert at writing daycare newsletters for parents. Output exactly one newsletter message within 100 characters.';
return [{ json: { newsletter_id: nl.newsletter_id, systemPrompt: systemPrompt, userContent: JSON.stringify(userContent) } }];

const nid = $('Build Regen Messages').first().json.newsletter_id;
const resp = $input.first().json;
let aiText = '';
try {
  aiText = resp.choices[0].message.content.trim().slice(0, 100);
} catch(e) {
  return [{ json: { error: 'AI text regeneration failed', newsletter_id: nid } }];
}
return [{ json: { ai_text: aiText, newsletter_id: nid } }];

const now = new Date();
const cutoff = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
const cutoffStr = cutoff.toISOString();
return [{ json: { cutoffStr: cutoffStr } }];

const cutoffStr = $('Compute Cutoff').first().json.cutoffStr;
const rows = $input.all().map(function(i) { return i.json; }).filter(function(i) { return !!i.newsletter_id; });
const count = rows.length;
return [{ json: { count: count, cutoffStr: cutoffStr, rows: rows } }];

const nid = $('Loop Delete').first().json.newsletter_id;
console.log('[Auto-delete] Deleted newsletter: ' + nid);
return [{ json: { deleted: nid } }];

const item = $input.first().json;
console.log('[Auto-delete] No expired records found. Cutoff: ' + item.cutoffStr);
return [{ json: { status: 'no_target', message: 'No expired records found', cutoffStr: item.cutoffStr } }];

const now = new Date();
const todayStr = now.toLocaleDateString('sv-SE', { timeZone: 'Asia/Tokyo' }).slice(0, 10);
const year = todayStr.slice(0, 4);
const jstDate = new Date(now.toLocaleString('en-US', { timeZone: 'Asia/Tokyo' }));
const day = jstDate.getDay();
if (day === 0 || day === 6) return [];
return [{ json: { todayStr: todayStr, year: year } }];

const todayStr = $('Check Weekend').first().json.todayStr;
const holidays = $input.first().json;
const isHoliday = Object.prototype.hasOwnProperty.call(holidays, todayStr);
if (isHoliday) return [];
return [{ json: { todayStr: todayStr } }];

const newsletters = $('Fetch Today Newsletters WF3').all().map(function(i) { return i.json; }).filter(function(i) { return Object.keys(i).length > 0; });
const children = $('Get All Children').all().map(function(i) { return i.json; });
const childMap = {};
for (const c of children) { childMap[c.child_id] = c.nickname || c.child_name; }
const total = newsletters.length;
const done = newsletters.filter(function(r) { return r.status === 'Approved' || r.status === 'Sent'; }).length;
const incomplete = newsletters.filter(function(r) { return r.status !== 'Approved' && r.status !== 'Sent'; });
const incompleteCount = incomplete.length;
const incompleteNames = incomplete.map(function(r) { return childMap[r.child_id] || r.child_id; }).join(', ');
const todayStr = $('Filter Holiday WF3').first().json.todayStr;
return [{ json: { total: total, done: done, incompleteCount: incompleteCount, incompleteNames: incompleteNames, todayStr: todayStr } }];

const item = $input.first().json;
const staffEmail = item.staffEmail || '';
return [{ json: Object.assign({}, item, { senderAddress: staffEmail }) }];

const item = $input.first().json;
console.log('[13:30 Check] All newsletters approved for ' + item.todayStr);
return [{ json: { status: 'all_done', message: 'All newsletters approved', todayStr: item.todayStr, total: item.total } }];

const now = new Date();
const todayStr = now.toLocaleDateString('sv-SE', { timeZone: 'Asia/Tokyo' }).slice(0, 10);
const year = todayStr.slice(0, 4);
const jstDate = new Date(now.toLocaleString('en-US', { timeZone: 'Asia/Tokyo' }));
const day = jstDate.getDay();
if (day === 0 || day === 6) return [];
return [{ json: { todayStr: todayStr, year: year } }];

const todayStr = $('Check Workday').first().json.todayStr;
const holidays = $input.first().json;
const isHoliday = Object.prototype.hasOwnProperty.call(holidays, todayStr);
if (isHoliday) return [];
return [{ json: { todayStr: todayStr } }];

const nl = $('Loop Newsletters').first().json;
const child = $input.first().json;
const nickname = child.nickname || child.child_name;
const parentEmail = child.parent_email;
const subject = "Today's update for " + nickname + " from daycare";
const bodyText = nl.final_text || nl.ai_text || '';
const body = '<p>' + bodyText + '</p>';
return [{ json: { newsletter_id: nl.newsletter_id, child_id: nl.child_id, parentEmail: parentEmail, subject: subject, body: body, nickname: nickname } }];
